-- Upsert every Season 1 official card design from KORION_NFT_CASE_MASTER_FINAL_V3 / Official_Cards_288.
-- Existing edition_size values are preserved. New designs receive the current grade default because edition_size is NOT NULL and > 0.
-- Rollback path: restore from DB backup or remove rows whose design_id was inserted by this migration and reset updated attributes from audit snapshot if needed.

CREATE TEMP TABLE tmp_official_cards_288 (
    season_code VARCHAR(10) NOT NULL,
    rarity_code VARCHAR(10) NOT NULL,
    design_no INT NOT NULL,
    design_id VARCHAR(40) NOT NULL,
    design_name VARCHAR(120) NOT NULL,
    edition_size INT NOT NULL,
    species VARCHAR(40) NOT NULL,
    faction VARCHAR(60) NOT NULL,
    job_class_code VARCHAR(40) NOT NULL,
    play_cost SMALLINT NOT NULL,
    attack INT NOT NULL,
    hp INT NOT NULL,
    move SMALLINT NOT NULL,
    range_stat SMALLINT NOT NULL,
    passive_code VARCHAR(40) NOT NULL,
    passive_name VARCHAR(80) NOT NULL,
    passive_desc TEXT NOT NULL,
    active_code VARCHAR(40) NOT NULL,
    active_name VARCHAR(80) NOT NULL,
    active_cost SMALLINT NOT NULL,
    active_desc TEXT NOT NULL
);

INSERT INTO gatcha_job_classes (code, name, description)
VALUES
    ('SUPPORT', '서포트', 'Official_Cards_288 role class'),
    ('ATTACK', '공격', 'Official_Cards_288 role class'),
    ('CONTROL', '제어', 'Official_Cards_288 role class'),
    ('SCOUT', '정찰', 'Official_Cards_288 role class'),
    ('DEFENSE', '방어', 'Official_Cards_288 role class'),
    ('SPECIAL', '특수', 'Official_Cards_288 role class')
ON CONFLICT (code) DO UPDATE
   SET name = EXCLUDED.name,
       description = COALESCE(gatcha_job_classes.description, EXCLUDED.description);

