DO $$
DECLARE
    official_count INT;
    missing_rarity_count INT;
BEGIN
    SELECT COUNT(*) INTO official_count FROM tmp_official_cards_288;
    IF official_count <> 288 THEN
        RAISE EXCEPTION 'Expected 288 official card rows, got %', official_count;
    END IF;

    SELECT COUNT(*) INTO missing_rarity_count
      FROM tmp_official_cards_288 src
      LEFT JOIN gatcha_seasons s ON s.code = src.season_code
      LEFT JOIN gatcha_rarities r ON r.season_id = s.id AND r.code = src.rarity_code
     WHERE r.id IS NULL;
    IF missing_rarity_count <> 0 THEN
        RAISE EXCEPTION 'Official card import has % rows with missing rarity mapping', missing_rarity_count;
    END IF;
END $$;

INSERT INTO gatcha_designs
    (rarity_id, design_id, design_no, name, image_url, edition_size, play_cost, attack, defense, hp, move, range,
     species, faction, passive_text, job_class_id, nft_enabled)
SELECT r.id, src.design_id, src.design_no, src.design_name, NULL, src.edition_size,
       src.play_cost, src.attack, 0, src.hp, src.move, src.range_stat,
       src.species, src.faction, src.passive_name || ': ' || src.passive_desc, jc.id, TRUE
  FROM tmp_official_cards_288 src
  JOIN gatcha_seasons s ON s.code = src.season_code
  JOIN gatcha_rarities r ON r.season_id = s.id AND r.code = src.rarity_code
  LEFT JOIN gatcha_job_classes jc ON jc.code = src.job_class_code
ON CONFLICT (rarity_id, design_no) DO UPDATE
   SET name = EXCLUDED.name,
       play_cost = EXCLUDED.play_cost,
       attack = EXCLUDED.attack,
       hp = EXCLUDED.hp,
       move = EXCLUDED.move,
       range = EXCLUDED.range,
       species = EXCLUDED.species,
       faction = EXCLUDED.faction,
       passive_text = EXCLUDED.passive_text,
       job_class_id = EXCLUDED.job_class_id,
       nft_enabled = TRUE,
       updated_at = NOW();

INSERT INTO gatcha_skills (code, name, kind, description, cost, skill_range, params)
SELECT passive_code, passive_name, 'PASSIVE', passive_desc, NULL, NULL, '{}'::jsonb FROM tmp_official_cards_288
UNION ALL
SELECT active_code, active_name, 'ACTIVE', active_desc, active_cost, range_stat, '{}'::jsonb FROM tmp_official_cards_288
ON CONFLICT (code) DO UPDATE
   SET name = EXCLUDED.name,
       kind = EXCLUDED.kind,
       description = EXCLUDED.description,
       cost = EXCLUDED.cost,
       skill_range = EXCLUDED.skill_range,
       params = EXCLUDED.params;

DELETE FROM gatcha_design_skills ds
 USING (
    SELECT d.design_id, src.passive_code, src.active_code
      FROM tmp_official_cards_288 src
      JOIN gatcha_seasons s ON s.code = src.season_code
      JOIN gatcha_rarities r ON r.season_id = s.id AND r.code = src.rarity_code
      JOIN gatcha_designs d ON d.rarity_id = r.id AND d.design_no = src.design_no
 ) target
 WHERE ds.design_id = target.design_id;

WITH target_designs AS (
    SELECT d.design_id, src.passive_code, src.active_code
      FROM tmp_official_cards_288 src
      JOIN gatcha_seasons s ON s.code = src.season_code
      JOIN gatcha_rarities r ON r.season_id = s.id AND r.code = src.rarity_code
      JOIN gatcha_designs d ON d.rarity_id = r.id AND d.design_no = src.design_no
)
INSERT INTO gatcha_design_skills (design_id, skill_id, slot)
SELECT target.design_id, s.id, skill_slots.slot
  FROM target_designs target
  CROSS JOIN LATERAL (
      VALUES (target.passive_code, 1), (target.active_code, 2)
  ) AS skill_slots(skill_code, slot)
  JOIN gatcha_skills s ON s.code = skill_slots.skill_code
ON CONFLICT (design_id, skill_id) DO UPDATE
   SET slot = EXCLUDED.slot;

DROP TABLE tmp_official_cards_288;
